/// <summary>
/// MPJ_5583_Fixed asset transations
/// </summary>
[ExtensionOf(tableStr(AssetTrans))]
final class METAssetTrans_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_5583_Fixed asset transations
    /// </summary>
    /// <param name = "assetTrans"> 
    /// get the table buffer
    /// </param>
    /// <returns>
    /// return proj id related to the asset 
    /// </returns>
    static display ProjId getProjId(AssetTrans assetTrans)
    {
        AssetTable  assetTable;
        ProjTable   projTable;
        ProjId      WBSElement;

        select firstonly AssetId from assetTrans
            join AssetId from assetTable
        where assetTable.AssetId == assetTrans.AssetId
            join AssetId from  projTable
        where projTable.AssetId == assetTable.AssetId;

        WBSElement = projTable.ProjId;
        return WBSElement;

    }
